#!/bin/bash

# Input data are generated by data_processing/02.joint_call/10.prepare_bench.sh 
input_path="input/fig1bc_benchmark/"
output_path="output/fig1bc_benchmark/"
sv_types="INS DEL"

[[ ! -d $output_path ]] && mkdir -p $output_path

# Benchmark by Truvari 3.5.0
for type in $sv_types; do
    ls ${input_path}/*${type}.vcf.gz | grep -v HG002_SVs_Tier1_v0.6.PASS | while read vcf; do
        name=$(basename $vcf)
        name=${name%.vcf.gz}

        truvari bench \
        -b ${input_path}/HG002_SVs_Tier1_v0.6.PASS.${type}.vcf.gz \
        -c $vcf \
        -o ${output_path}/${name} \
        --pctsim 0 \
        -r 1000 \
        --no-ref c \
        --includebed ${input_path}/HG002_SVs_Tier1_v0.6.bed
    done
done

# extract results from truvari report
# note: for ensemble call, this generate metrics when RF score cutoff == 0
echo -e "method\tsv_type\tTP\tFP\tFN\tprecision\trecall\tf1" \
> ${output_path}/summary.all.txt
ls ${output_path} | grep -v summary.all.txt | while read summary_folder; do
    summary_folder=${output_path}/${summary_folder}
    summary_report=${summary_folder}/summary.txt

    name=$(basename $summary_folder)
    type=${name##*.}
    TP=$(grep '"TP-call"' $summary_report | awk '{print $2}' | sed 's/,//g')
    FP=$(grep '"FP"' $summary_report | awk '{print $2}' | sed 's/,//g')
    FN=$(grep '"FN"' $summary_report | awk '{print $2}' | sed 's/,//g')
    precision=$(grep '"precision"' $summary_report | awk '{print $2}' | sed 's/,//g')
    recall=$(grep '"recall"' $summary_report | awk '{print $2}' | sed 's/,//g')
    f1=$(grep '"f1"' $summary_report | awk '{print $2}' | sed 's/,//g')

    echo -e "$name\t$type\t$TP\t$FP\t$FN\t$precision\t$recall\t$f1"
done >> ${output_path}/summary.all.txt

# calculate metrics for different RF score cutoffs
bcftools query -f '%ID\t%RF_SCORE\t1\n' ${output_path}/ensemble.INS/tp-call.vcf \
> ${output_path}/ensemble.INS.score.txt
bcftools query -f '%ID\t%RF_SCORE\t0\n' ${output_path}/ensemble.INS/fp.vcf \
>> ${output_path}/ensemble.INS.score.txt

bcftools query -f '%ID\t%RF_SCORE\t1\n' ${output_path}/ensemble.DEL/tp-call.vcf \
> ${output_path}/ensemble.DEL.score.txt
bcftools query -f '%ID\t%RF_SCORE\t0\n' ${output_path}/ensemble.DEL/fp.vcf \
>> ${output_path}/ensemble.DEL.score.txt

# visualization
Rscript --vanilla -e "
library(readr)
library(dplyr)
library(ggplot2)

output_path='${output_path}'

df_baseline <- read_tsv(paste0(output_path, '/summary.all.txt'))
df_ins <- read_tsv(paste0(output_path, '/ensemble.INS.score.txt'), col_names=c('ID', 'RF_SCORE', 'TP'))
df_del <- read_tsv(paste0(output_path, '/ensemble.DEL.score.txt'), col_names=c('ID', 'RF_SCORE', 'TP'))

# get total number of positive SVs in benchmark sites
ins_p <- filter(df_baseline, method == 'ensemble.INS') %>% mutate(P = TP + FN) %>% pull(P)
del_p <- filter(df_baseline, method == 'ensemble.DEL') %>% mutate(P = TP + FN) %>% pull(P)

df_summary <- tibble()

for (cutoff in seq(0, 0.999, 0.001)) {
    tp_ins <- filter(df_ins, RF_SCORE >= cutoff, TP == 1) %>% nrow()
    fp_ins <- filter(df_ins, RF_SCORE >= cutoff, TP == 0) %>% nrow()
    recall_ins <- tp_ins / ins_p
    precision_ins <- tp_ins / (tp_ins + fp_ins)
    f1_ins <- 2 * precision_ins * recall_ins / (precision_ins + recall_ins)

    tp_del <- filter(df_del, RF_SCORE >= cutoff, TP == 1) %>% nrow()
    fp_del <- filter(df_del, RF_SCORE >= cutoff, TP == 0) %>% nrow()
    recall_del <- tp_del / del_p
    precision_del <- tp_del / (tp_del + fp_del)
    f1_del <- 2 * precision_del * recall_del / (precision_del + recall_del)

    df_summary <- bind_rows(df_summary, tibble(
        cutoff = cutoff,
        precision_ins = precision_ins,
        recall_ins = recall_ins,
        f1_ins = f1_ins,
        precision_del = precision_del,
        recall_del = recall_del,
        f1_del = f1_del
    ))
}

# Fig.1b INS
pdf(paste0(output_path, '/fig1b.INS_benchmark.pdf'))
ggplot() +
    geom_point(aes(recall, precision), data=filter(df_baseline, sv_type=='INS', ! grepl('ensemble', method))) + 
    geom_line(aes(recall_ins, precision_ins), data=df_summary, color='blue') +
    ylim(0.6, 1) + xlim(0.8, 1)
dev.off()

# Fig.1c DEL
pdf(paste0(output_path, '/fig1c.DEL_benchmark.pdf'))
ggplot() +
    geom_point(aes(recall, precision), data=filter(df_baseline, sv_type=='DEL', ! grepl('ensemble', method))) + 
    geom_line(aes(recall_del, precision_del), data=df_summary, color='blue') +
    ylim(0.9, 1) + xlim(0.9, 1)
dev.off()
"